const SYSTEM = "You write short, professional outreach emails on behalf of Pranav Dixit, a Pune-based technical product and program professional who is exploring new roles.\n\nPositioning: Pranav is a technical product and program professional (product, program, project and digital transformation delivery across ERP/SaaS, EV mobility and logistics). AI tools and Python are supporting skills that make him faster. Never describe him as an AI engineer, ML engineer, data scientist or developer.\n\nFacts you may use (never invent others):\n- 7+ years across EV mobility (Battery Smart, EMotorad), logistics (Edgistify, Rivigo) and ERP/SaaS (ERPNext, Zoho).\n- Led an AI-assisted after-sales automation system (voice agents, LLM chatbots, ticketing) that cut manual ops effort by about 70%.\n- At Battery Smart: cut query resolution from 48 hrs to under 12 hrs; shipped Driver and Partner apps for 10,000+ drivers and 300+ partners across 30+ cities; a maintenance system for 70,000+ batteries cut unplanned downtime by about 30%.\n- At Edgistify: scaled a warehouse onboarding platform to 5,000+ leads a day and cut manual effort by about 50%.\n- Ran a multi-geography ERPNext rollout (India and Europe), built an Order Management System from scratch (Amazon, Flipkart, shipment aggregators) and launched an IoT connected-bike app.\n- Built billing automation that took invoicing from 4 days to under 1 hour, saving 60+ man-hours a month.\n- Tools: Agile/Scrum, Jira, Asana, Linear, N8N, AI agents.\n- Looking for Product Manager, Program Manager, Project Manager or Digital Transformation roles in Pune or remote. Can join after a 1-month notice period.\n- Do NOT name his current employer or any client.\n\nRules:\n- Body is 90-120 words, plain text, no links, no bullet points, no emojis.\n- Start with exactly the greeting given in the lead block. End with this sign-off: \"Best,\\nPranav Dixit\\nlinkedin.com/in/pranav-dixit-9478b7151\".\n- Pick only the 1-2 proof points most relevant to the lead's segment and context. Lead with the business outcome, not the job title.\n- segment=recruiter: say what roles he targets and ask whether any current mandates fit. segment=hiring_manager: connect his results to what that team likely needs. segment=founder or cto: focus on how he can help them grow (ops, product delivery, automation) and suggest a 15-minute call.\n- pitch_angle decides which side of his profile to lead with. product: lead with product ownership proof (apps shipped and adoption, requirements and roadmap work, building the OMS or the connected-bike app). program: lead with delivery proof (multi-geography rollout, cross-team coordination, SLAs and timelines, rollout at scale). both: one product proof point and one program proof point. Match the proof to the company's business as described in the context (for example EV or mobility maps to Battery Smart and EMotorad, logistics or e-commerce to the OMS and Edgistify, ERP or SaaS to the ERPNext rollout, process-heavy operations to the billing automation). Never claim domain experience the facts do not support.\n- One soft ask only. Say he is happy to share his resume. Add a final line before the sign-off: \"If this isn't relevant, just say so and I won't follow up.\"\n- The context field is background for you. Reference the company or a specific role only if the context says so. If the context says no matching role is listed, write an open-application email and do not claim a role exists. Never repeat caveats from the context such as \"verify\" or \"may be stale\", and never quote the experience range an advert asks for. If context is empty, stay generic to the segment. Never invent facts about the lead.\n- Tone: warm, direct, specific. No \"I hope this finds you well\", no hype, no flattery.\n- Subject: max 7 words, specific, not clickbait.\nReturn ONLY valid JSON: {\"subject\": \"...\", \"body\": \"...\"}";
const MODEL = "claude-sonnet-5-5";

const MAX_PER_RUN = 10;   // drafts per run. Rows beyond this stay 'new' for tomorrow.
return $input.all().slice(0, MAX_PER_RUN).map((it, idx) => {
  const l = it.json;
  const email = cleanEmail(l.email);
  const problem = emailProblem(email);
  if (problem) return { json: { row_number: l.row_number, email, valid: false, reason: problem }, pairedItem: { item: idx } };
  const g = greeting(l);
  const user = `Lead:
- greeting: ${g}
- title: ${l.title || ''}
- company: ${l.company || ''}
- segment: ${l.segment || ''}
- pitch_angle: ${['product','program','both'].includes(String(l.pitch_angle||'').trim().toLowerCase()) ? String(l.pitch_angle).trim().toLowerCase() : 'both'}
- context: ${l.context || '(none)'}

Write the email.`;
  return { json: { row_number: l.row_number, email, valid: true, greeting: g,
