return $input.all().map((it) => {
  const j = it.json;
  const raw = j.From || (j.from && j.from.value && j.from.value[0] && j.from.value[0].address) || '';
  const m = String(raw).match(/[\w.+'-]+@[\w-]+\.[\w.-]+/);
  const from = m ? m[0].toLowerCase() : '';
  const subject = String(j.Subject || j.subject || '');
  return { json: {
    from, threadId: j.threadId || '', snippet: String(j.snippet || '').toLowerCase(), subject,
    isBounce: /mailer-daemon|postmaster/i.test(from) || /delivery status notification|undeliverable|delivery failure|returned mail/i.test(subject),
    isAuto: /automatic reply|auto-reply|autoreply|out of office/i.test(subject)
  } };
}).filter((x) => x.json.from);

const ACTIVE = ['sent', 'followup_pending_approval', 'fu_approved', 'followup_sent'];
const mails = $('E2 Read mail details').all().map((i) => i.json);
const rows = $input.all().map((i) => i.json).filter((r) => ACTIVE.includes(String(r.status || '').trim()));
const found = new Map();
for (const m of mails) {
  if (m.isAuto) continue;
  for (const r of rows) {
    const email = String(r.email || '').trim().toLowerCase();
    if (!email) continue;
    if (m.isBounce) {
      if (m.snippet.includes(email)) found.set(r.row_number, 'bounced');
    } else if ((r.thread_id && m.threadId === String(r.thread_id).trim()) || m.from === email) {
      if (found.get(r.row_number) !== 'bounced') found.set(r.row_number, 'replied');
    }
  }
}
return [...found.entries()].map(([row_number, status]) => ({ json: { row_number, status } }));
